if str(vars.get('id_state') or '') == 'verified':
    import json
    def _d(result):
        if isinstance(result, dict):
            result.pop('header', None)
            d = result.get('data')
            if isinstance(d, dict):
                return d
        return None
    def _flag(x):
        return str(x).lower() == 'true'
    def _load(name, default):
        try:
            v = vars.get(name)
            if isinstance(v, str) and v:
                return json.loads(v)
            if isinstance(v, (list, dict)):
                return v
        except Exception:
            pass
        return default
    def _count(name):
        n = int(float(vars.get(name) or 0)) + 1
        vars[name] = str(n)
        return n
    def _block(b):
        # the platform sends the request even with an empty body and skips the post-hook on an error, so a blocked call sends values no bank accepts
        for k in list(b):
            if k != 'customer_id':
                b[k] = 'blocked'
    OUT = {
     "unclear": {
      "outcome": "not_reached",
      "reason": "unclear"
     },
     "callback": {
      "outcome": "not_reached",
      "reason": "callback"
     },
     "no_callback": {
      "outcome": "not_reached",
      "reason": "no_callback"
     },
