      "when": "The customer mentions illness, a death in the family or job loss. Say one short sentence of sympathy, make no persuasion attempt, and offer to connect them with the customer support team. If they accept, call transfer_to_agent with queue support. Add no notes.",
      "outcome": "transferred",
      "reason": "support"
     }
    ]
    ENDS = {
     "refused": {
      "key": "refused",
      "meaning": "Persuasion attempts are used up after flat refusals, or the customer said twice after verification that they do not want to talk.",
      "outcome": "no_promise",
      "reason": "refused",
      "note_reason": "refused"
     },
     "hardship": {
      "key": "hardship",
      "meaning": "The customer mentioned illness, a death in the family or job loss and declined the transfer to customer support.",
      "outcome": "no_promise",
      "reason": "hardship",
      "note_reason": "hardship"
     },
     "dispute": {
      "key": "dispute",
      "meaning": "The customer says the debt is not theirs, they never had the product, or the product was closed or paid off in the past.",
      "outcome": "no_promise",
      "reason": "dispute",
      "note_reason": "dispute"
     },
     "paid": {
      "key": "paid",
      "meaning": "The customer says they already paid this past-due amount.",
      "outcome": "paid",
      "reason": "",
      "note_reason": "paid"
     },
     "service_error": {
      "key": "service_error",
      "meaning": "create_promise failed twice, so the promise could not be recorded.",
      "outcome": "no_promise",
      "reason": "service_error",
      "note_reason": "service_error"
     }
    }
    NOTE_KEY = {
     "refused": "refused",
     "hardship": "hardship",
     "dispute": "dispute",
     "paid": "paid",
     "service_error": "service_error"
    }
    try:
        promises, notes = _load('promises_recorded', []), _load('notes_recorded', [])
        keys = list(ENDS.keys())
