        o = None
        if vars.get('transfer_state') == 'done':
            q = str(vars.get('transfer_queue') or '')
            o = next((t for t in TRANSFERS if str(t.get('queue')) == q), TRANSFERS[0] if TRANSFERS else None)
        elif promises:
