        elif notes:
            order = [str(f.get('product_id')) for f in _load('product_facts_json', [])]
            notes.sort(key=lambda n: order.index(str(n.get('product_id'))) if str(n.get('product_id')) in order else 99)
            ks = [NOTE_KEY.get(str(n.get('reason')), default) for n in notes]
            key = 'paid' if ('paid' in ENDS and all(k == 'paid' for k in ks)) else next((k for k in ks if k != 'paid'), default)
